window.__code__ = window.__code__ || {};
window.__code__["auth-py"] = {"code_id": "auth-py", "kind": "src", "title": "auth.py", "source_path": "QwenPaw-main/src/qwenpaw/app/auth.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;Authentication module: password hashing, JWT tokens, <span class=\"c-kw\">and</span> FastAPI middleware.</span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">Login <span class=\"c-kw\">is</span> disabled by default <span class=\"c-kw\">and</span> only enabled when the environment</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\">variable ``QWENPAW_AUTH_ENABLED`` <span class=\"c-kw\">is</span> set to a truthy value (``true``,</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\">``1``, ``yes``).  Credentials are created through a web-based</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\">registration flow rather than environment variables, so that agents</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\">running inside the process cannot read plaintext passwords.</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\">Single-user design: only one account can be registered.  If the user</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">forgets their password, delete ``auth.json`` <span class=\"c-kw\">from</span> ``SECRET_DIR`` <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">restart the service to re-register.</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">Uses only Python stdlib (hashlib, hmac, secrets) to avoid adding new</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">dependencies.  The password <span class=\"c-kw\">is</span> stored <span class=\"c-kw\">as</span> a salted SHA-256 hash <span class=\"c-kw\">in</span></span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">``auth.json`` under ``SECRET_DIR``.</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">from</span> __future__ <span class=\"c-kw\">import</span> annotations</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\"><span class=\"c-kw\">import</span> hashlib</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\"><span class=\"c-kw\">import</span> hmac</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\"><span class=\"c-kw\">import</span> json</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\"><span class=\"c-kw\">import</span> logging</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\"><span class=\"c-kw\">import</span> secrets</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\"><span class=\"c-kw\">import</span> time</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> Optional</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\"><span class=\"c-kw\">from</span> fastapi <span class=\"c-kw\">import</span> Request, Response</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\"><span class=\"c-kw\">from</span> starlette.middleware.base <span class=\"c-kw\">import</span> BaseHTTPMiddleware</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..constant <span class=\"c-kw\">import</span> SECRET_DIR, EnvVarLoader</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..security.secret_store <span class=\"c-kw\">import</span> (</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">    AUTH_SECRET_FIELDS,</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    decrypt_dict_fields,</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    encrypt_dict_fields,</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">    is_encrypted,</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">logger = logging.getLogger(__name__)</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">AUTH_FILE = SECRET_DIR / <span class=\"c-str\">&quot;auth.json&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\"><span class=\"c-com\"># Token validity: 7 days (default)</span></span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">TOKEN_EXPIRY_SECONDS = 7 * 24 * 3600</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\"><span class=\"c-com\"># Maximum token validity: 100 years (for \u00005\u0000 tokens)</span></span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">TOKEN_EXPIRY_MAX = 100 * 365 * 24 * 3600</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\"><span class=\"c-com\"># Paths that do NOT require authentication</span></span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">_PUBLIC_PATHS: frozenset[str] = frozenset(</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">    {</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">        <span class=\"c-str\">&quot;/api/auth/login&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">        <span class=\"c-str\">&quot;/api/auth/status&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">        <span class=\"c-str\">&quot;/api/auth/register&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">        <span class=\"c-str\">&quot;/api/version&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">        <span class=\"c-str\">&quot;/api/settings/language&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">        <span class=\"c-str\">&quot;/api/settings/upload-limit&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">        <span class=\"c-str\">&quot;/api/frontend_plugin&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">    },</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\"><span class=\"c-com\"># Prefixes that do NOT require authentication (static assets)</span></span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\"><span class=\"c-com\"># /api/frontend_plugin/ is safe: only read-only GET handlers are registered</span></span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\"><span class=\"c-com\"># under that prefix (list + static file serving).  All write operations</span></span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\"><span class=\"c-com\"># remain under /api/plugins/ which requires authentication.</span></span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">_PUBLIC_PREFIXES: tuple[str, ...] = (</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">    <span class=\"c-str\">&quot;/assets/&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">    <span class=\"c-str\">&quot;/logo.png&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">    <span class=\"c-str\">&quot;/qwenpaw-symbol.svg&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">    <span class=\"c-str\">&quot;/api/frontend_plugin/&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\"><span class=\"c-com\"># Helpers (reuse SECRET_DIR patterns from envs/store.py)</span></span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _chmod_best_effort(path, mode: int) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">        os.chmod(path, mode)</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">    <span class=\"c-kw\">except</span> OSError:</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">        <span class=\"c-kw\">pass</span></span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _prepare_secret_parent(path) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">    path.parent.mkdir(parents=<span class=\"c-kw\">True</span>, exist_ok=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">    _chmod_best_effort(path.parent, 0o700)</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\"><span class=\"c-com\"># Password hashing (salted SHA-256, no external deps)</span></span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _hash_password(</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">    password: str,</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">    salt: Optional[str] = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">) -&gt; tuple[str, str]:</span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Hash *password* with *salt*.  Returns ``(hash_hex, salt_hex)``.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> salt <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">        salt = secrets.token_hex(16)</span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">    h = hashlib.sha256((salt + password).encode(<span class=\"c-str\">&quot;utf-8&quot;</span>)).hexdigest()</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> h, salt</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\"><span class=\"c-kw\">def</span> verify_password(password: str, stored_hash: str, salt: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Verify *password* against a stored hash.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">    h, _ = _hash_password(password, salt)</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> hmac.compare_digest(h, stored_hash)</span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\"><span class=\"c-com\"># Token generation / verification (HMAC-SHA256, no PyJWT needed)</span></span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _get_jwt_secret() -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Return the signing secret, creating one if absent.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">    secret = data.get(<span class=\"c-str\">&quot;jwt_secret&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> secret:</span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">        secret = secrets.token_hex(32)</span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;jwt_secret&quot;</span>] = secret</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">        _save_auth_data(data)</span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> secret</span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\"><span class=\"c-kw\">def</span> create_token(username: str, expiry_seconds: Optional[int] = <span class=\"c-kw\">None</span>) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Create an HMAC-signed token: ``base64(payload).signature``.</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">        username: The username to encode <span class=\"c-kw\">in</span> the token.</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">        expiry_seconds: Custom expiry time <span class=\"c-kw\">in</span> seconds.</span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">            Use -1 <span class=\"c-kw\">or</span> 0 <span class=\"c-kw\">for</span> permanent tokens.</span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">            Defaults to TOKEN_EXPIRY_SECONDS (7 days).</span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">    <span class=\"c-kw\">import</span> base64</span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> expiry_seconds <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">        expiry_seconds = TOKEN_EXPIRY_SECONDS</span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">    <span class=\"c-kw\">elif</span> expiry_seconds &lt;= 0:</span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">        <span class=\"c-com\"># Permanent token: 100 years</span></span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">        expiry_seconds = TOKEN_EXPIRY_MAX</span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">    <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">        <span class=\"c-com\"># Cap at maximum allowed expiry</span></span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">        expiry_seconds = min(expiry_seconds, TOKEN_EXPIRY_MAX)</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">    secret = _get_jwt_secret()</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">    <span class=\"c-com\"># Generate unique token ID (jti) for revocation support</span></span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">    token_id = secrets.token_hex(16)</span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">    payload = json.dumps(</span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">        {</span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">            <span class=\"c-str\">&quot;sub&quot;</span>: username,</span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">            <span class=\"c-str\">&quot;exp&quot;</span>: int(time.time()) + expiry_seconds,</span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">            <span class=\"c-str\">&quot;iat&quot;</span>: int(time.time()),</span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">            <span class=\"c-str\">&quot;jti&quot;</span>: token_id,  <span class=\"c-com\"># JWT ID for individual revocation</span></span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">        },</span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">    payload_b64 = base64.urlsafe_b64encode(payload.encode()).decode()</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">    sig = hmac.new(</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">        secret.encode(),</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">        payload_b64.encode(),</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">        hashlib.sha256,</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">    ).hexdigest()</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> f<span class=\"c-str\">&quot;{payload_b64}.{sig}&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\"><span class=\"c-kw\">def</span> verify_token(token: str) -&gt; Optional[str]:</span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Verify *token*, <span class=\"c-kw\">return</span> username <span class=\"c-kw\">if</span> valid, ``<span class=\"c-kw\">None</span>`` otherwise.</span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">    Also checks <span class=\"c-kw\">if</span> the token has been revoked (appears <span class=\"c-kw\">in</span> the revocation list).</span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">    <span class=\"c-kw\">import</span> base64</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">        parts = token.split(<span class=\"c-str\">&quot;.&quot;</span>, 1)</span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> len(parts) != 2:</span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">        payload_b64, sig = parts</span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">        secret = _get_jwt_secret()</span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">        expected_sig = hmac.new(</span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">            secret.encode(),</span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">            payload_b64.encode(),</span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">            hashlib.sha256,</span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">        ).hexdigest()</span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> hmac.compare_digest(sig, expected_sig):</span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">        payload = json.loads(base64.urlsafe_b64decode(payload_b64))</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> payload.get(<span class=\"c-str\">&quot;exp&quot;</span>, 0) &lt; time.time():</span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">        <span class=\"c-com\"># Check if token is revoked</span></span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">        jti = payload.get(<span class=\"c-str\">&quot;jti&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> jti <span class=\"c-kw\">and</span> _is_token_revoked(jti):</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> payload.get(<span class=\"c-str\">&quot;sub&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">    <span class=\"c-kw\">except</span> (json.JSONDecodeError, KeyError, ValueError, TypeError) <span class=\"c-kw\">as</span> exc:</span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">        logger.debug(<span class=\"c-str\">&quot;Token verification failed: %s&quot;</span>, exc)</span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\"><span class=\"c-com\"># Auth data persistence (auth.json in SECRET_DIR)</span></span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"209\"><span class=\"c-no\">209</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"210\"><span class=\"c-no\">210</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _load_auth_data() -&gt; dict:</span></div>\n<div class=\"c-line\" data-line=\"211\"><span class=\"c-no\">211</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Load ``auth.json`` <span class=\"c-kw\">from</span> ``SECRET_DIR``.</span></div>\n<div class=\"c-line\" data-line=\"212\"><span class=\"c-no\">212</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"213\"><span class=\"c-no\">213</span><span class=\"c-src\">    Returns the parsed dict, <span class=\"c-kw\">or</span> a sentinel <span class=\"c-kw\">with</span> ``_auth_load_error``</span></div>\n<div class=\"c-line\" data-line=\"214\"><span class=\"c-no\">214</span><span class=\"c-src\">    set to ``<span class=\"c-kw\">True</span>`` when the file exists but cannot be read/parsed so</span></div>\n<div class=\"c-line\" data-line=\"215\"><span class=\"c-no\">215</span><span class=\"c-src\">    that callers can fail closed instead of silently bypassing auth.</span></div>\n<div class=\"c-line\" data-line=\"216\"><span class=\"c-no\">216</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"217\"><span class=\"c-no\">217</span><span class=\"c-src\">    Encrypted fields (``jwt_secret``) are transparently decrypted.</span></div>\n<div class=\"c-line\" data-line=\"218\"><span class=\"c-no\">218</span><span class=\"c-src\">    Legacy plaintext values trigger an automatic re-encryption.</span></div>\n<div class=\"c-line\" data-line=\"219\"><span class=\"c-no\">219</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"220\"><span class=\"c-no\">220</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> AUTH_FILE.is_file():</span></div>\n<div class=\"c-line\" data-line=\"221\"><span class=\"c-no\">221</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"222\"><span class=\"c-no\">222</span><span class=\"c-src\">            <span class=\"c-kw\">with</span> open(AUTH_FILE, <span class=\"c-str\">&quot;r&quot;</span>, encoding=<span class=\"c-str\">&quot;utf-8&quot;</span>) <span class=\"c-kw\">as</span> fh:</span></div>\n<div class=\"c-line\" data-line=\"223\"><span class=\"c-no\">223</span><span class=\"c-src\">                data = json.load(fh)</span></div>\n<div class=\"c-line\" data-line=\"224\"><span class=\"c-no\">224</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"225\"><span class=\"c-no\">225</span><span class=\"c-src\">            needs_rewrite = any(</span></div>\n<div class=\"c-line\" data-line=\"226\"><span class=\"c-no\">226</span><span class=\"c-src\">                isinstance(data.get(field), str)</span></div>\n<div class=\"c-line\" data-line=\"227\"><span class=\"c-no\">227</span><span class=\"c-src\">                <span class=\"c-kw\">and</span> data.get(field)</span></div>\n<div class=\"c-line\" data-line=\"228\"><span class=\"c-no\">228</span><span class=\"c-src\">                <span class=\"c-kw\">and</span> <span class=\"c-kw\">not</span> is_encrypted(data[field])</span></div>\n<div class=\"c-line\" data-line=\"229\"><span class=\"c-no\">229</span><span class=\"c-src\">                <span class=\"c-kw\">for</span> field <span class=\"c-kw\">in</span> AUTH_SECRET_FIELDS</span></div>\n<div class=\"c-line\" data-line=\"230\"><span class=\"c-no\">230</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"231\"><span class=\"c-no\">231</span><span class=\"c-src\">            data = decrypt_dict_fields(data, AUTH_SECRET_FIELDS)</span></div>\n<div class=\"c-line\" data-line=\"232\"><span class=\"c-no\">232</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> needs_rewrite:</span></div>\n<div class=\"c-line\" data-line=\"233\"><span class=\"c-no\">233</span><span class=\"c-src\">                <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"234\"><span class=\"c-no\">234</span><span class=\"c-src\">                    _save_auth_data(data)</span></div>\n<div class=\"c-line\" data-line=\"235\"><span class=\"c-no\">235</span><span class=\"c-src\">                <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> enc_err:</span></div>\n<div class=\"c-line\" data-line=\"236\"><span class=\"c-no\">236</span><span class=\"c-src\">                    logger.debug(</span></div>\n<div class=\"c-line\" data-line=\"237\"><span class=\"c-no\">237</span><span class=\"c-src\">                        <span class=\"c-str\">&quot;Deferred plaintext→encrypted migration for&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"238\"><span class=\"c-no\">238</span><span class=\"c-src\">                        <span class=\"c-str\">&quot; auth.json: %s&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"239\"><span class=\"c-no\">239</span><span class=\"c-src\">                        enc_err,</span></div>\n<div class=\"c-line\" data-line=\"240\"><span class=\"c-no\">240</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"241\"><span class=\"c-no\">241</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> data</span></div>\n<div class=\"c-line\" data-line=\"242\"><span class=\"c-no\">242</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> (json.JSONDecodeError, OSError) <span class=\"c-kw\">as</span> exc:</span></div>\n<div class=\"c-line\" data-line=\"243\"><span class=\"c-no\">243</span><span class=\"c-src\">            logger.error(<span class=\"c-str\">&quot;Failed to load auth file %s: %s&quot;</span>, AUTH_FILE, exc)</span></div>\n<div class=\"c-line\" data-line=\"244\"><span class=\"c-no\">244</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> {<span class=\"c-str\">&quot;_auth_load_error&quot;</span>: <span class=\"c-kw\">True</span>}</span></div>\n<div class=\"c-line\" data-line=\"245\"><span class=\"c-no\">245</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> {}</span></div>\n<div class=\"c-line\" data-line=\"246\"><span class=\"c-no\">246</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"247\"><span class=\"c-no\">247</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"248\"><span class=\"c-no\">248</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _save_auth_data(data: dict) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"249\"><span class=\"c-no\">249</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Save ``auth.json`` to ``SECRET_DIR`` <span class=\"c-kw\">with</span> restrictive permissions.</span></div>\n<div class=\"c-line\" data-line=\"250\"><span class=\"c-no\">250</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"251\"><span class=\"c-no\">251</span><span class=\"c-src\">    Sensitive fields (``jwt_secret``) are encrypted before writing.</span></div>\n<div class=\"c-line\" data-line=\"252\"><span class=\"c-no\">252</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"253\"><span class=\"c-no\">253</span><span class=\"c-src\">    _prepare_secret_parent(AUTH_FILE)</span></div>\n<div class=\"c-line\" data-line=\"254\"><span class=\"c-no\">254</span><span class=\"c-src\">    encrypted_data = encrypt_dict_fields(data, AUTH_SECRET_FIELDS)</span></div>\n<div class=\"c-line\" data-line=\"255\"><span class=\"c-no\">255</span><span class=\"c-src\">    <span class=\"c-kw\">with</span> open(AUTH_FILE, <span class=\"c-str\">&quot;w&quot;</span>, encoding=<span class=\"c-str\">&quot;utf-8&quot;</span>) <span class=\"c-kw\">as</span> f:</span></div>\n<div class=\"c-line\" data-line=\"256\"><span class=\"c-no\">256</span><span class=\"c-src\">        json.dump(encrypted_data, f, indent=2, ensure_ascii=<span class=\"c-kw\">False</span>)</span></div>\n<div class=\"c-line\" data-line=\"257\"><span class=\"c-no\">257</span><span class=\"c-src\">    _chmod_best_effort(AUTH_FILE, 0o600)</span></div>\n<div class=\"c-line\" data-line=\"258\"><span class=\"c-no\">258</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"259\"><span class=\"c-no\">259</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"260\"><span class=\"c-no\">260</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"261\"><span class=\"c-no\">261</span><span class=\"c-src\"><span class=\"c-com\"># Token revocation (blacklist management)</span></span></div>\n<div class=\"c-line\" data-line=\"262\"><span class=\"c-no\">262</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"263\"><span class=\"c-no\">263</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"264\"><span class=\"c-no\">264</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"265\"><span class=\"c-no\">265</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _is_token_revoked(jti: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"266\"><span class=\"c-no\">266</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Check <span class=\"c-kw\">if</span> a token ID (jti) <span class=\"c-kw\">is</span> <span class=\"c-kw\">in</span> the revocation list.</span></div>\n<div class=\"c-line\" data-line=\"267\"><span class=\"c-no\">267</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"268\"><span class=\"c-no\">268</span><span class=\"c-src\">    Uses O(1) dict lookup via revoked_tokens_meta <span class=\"c-kw\">for</span> performance.</span></div>\n<div class=\"c-line\" data-line=\"269\"><span class=\"c-no\">269</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"270\"><span class=\"c-no\">270</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"271\"><span class=\"c-no\">271</span><span class=\"c-src\">    meta = data.get(<span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span>, {})</span></div>\n<div class=\"c-line\" data-line=\"272\"><span class=\"c-no\">272</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> jti <span class=\"c-kw\">in</span> meta</span></div>\n<div class=\"c-line\" data-line=\"273\"><span class=\"c-no\">273</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"274\"><span class=\"c-no\">274</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"275\"><span class=\"c-no\">275</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _add_to_revocation_list(jti: str, exp: int) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"276\"><span class=\"c-no\">276</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Add a token ID to the revocation list <span class=\"c-kw\">with</span> its expiry time.</span></div>\n<div class=\"c-line\" data-line=\"277\"><span class=\"c-no\">277</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"278\"><span class=\"c-no\">278</span><span class=\"c-src\">    Uses revoked_tokens_meta dict <span class=\"c-kw\">for</span> O(1) lookups. The revoked_tokens list</span></div>\n<div class=\"c-line\" data-line=\"279\"><span class=\"c-no\">279</span><span class=\"c-src\">    <span class=\"c-kw\">is</span> kept <span class=\"c-kw\">for</span> backwards compatibility but <span class=\"c-kw\">not</span> used <span class=\"c-kw\">for</span> membership checks.</span></div>\n<div class=\"c-line\" data-line=\"280\"><span class=\"c-no\">280</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"281\"><span class=\"c-no\">281</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"282\"><span class=\"c-no\">282</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> data.get(<span class=\"c-str\">&quot;_auth_load_error&quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"283\"><span class=\"c-no\">283</span><span class=\"c-src\">        <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"284\"><span class=\"c-no\">284</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"285\"><span class=\"c-no\">285</span><span class=\"c-src\">    <span class=\"c-com\"># Initialize revoked_tokens_meta if not present</span></span></div>\n<div class=\"c-line\" data-line=\"286\"><span class=\"c-no\">286</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> data:</span></div>\n<div class=\"c-line\" data-line=\"287\"><span class=\"c-no\">287</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span>] = {}</span></div>\n<div class=\"c-line\" data-line=\"288\"><span class=\"c-no\">288</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"289\"><span class=\"c-no\">289</span><span class=\"c-src\">    <span class=\"c-com\"># O(1) check using dict</span></span></div>\n<div class=\"c-line\" data-line=\"290\"><span class=\"c-no\">290</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> jti <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> data[<span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span>]:</span></div>\n<div class=\"c-line\" data-line=\"291\"><span class=\"c-no\">291</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span>][jti] = exp</span></div>\n<div class=\"c-line\" data-line=\"292\"><span class=\"c-no\">292</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"293\"><span class=\"c-no\">293</span><span class=\"c-src\">        <span class=\"c-com\"># Also add to list for backwards compatibility</span></span></div>\n<div class=\"c-line\" data-line=\"294\"><span class=\"c-no\">294</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-str\">&quot;revoked_tokens&quot;</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> data:</span></div>\n<div class=\"c-line\" data-line=\"295\"><span class=\"c-no\">295</span><span class=\"c-src\">            data[<span class=\"c-str\">&quot;revoked_tokens&quot;</span>] = []</span></div>\n<div class=\"c-line\" data-line=\"296\"><span class=\"c-no\">296</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;revoked_tokens&quot;</span>].append(jti)</span></div>\n<div class=\"c-line\" data-line=\"297\"><span class=\"c-no\">297</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"298\"><span class=\"c-no\">298</span><span class=\"c-src\">    _save_auth_data(data)</span></div>\n<div class=\"c-line\" data-line=\"299\"><span class=\"c-no\">299</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"300\"><span class=\"c-no\">300</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"301\"><span class=\"c-no\">301</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _clean_expired_revocations() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"302\"><span class=\"c-no\">302</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"303\"><span class=\"c-no\">303</span><span class=\"c-src\">    Remove expired tokens <span class=\"c-kw\">from</span> the revocation list to prevent unbounded growth.</span></div>\n<div class=\"c-line\" data-line=\"304\"><span class=\"c-no\">304</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"305\"><span class=\"c-no\">305</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"306\"><span class=\"c-no\">306</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> data.get(<span class=\"c-str\">&quot;_auth_load_error&quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"307\"><span class=\"c-no\">307</span><span class=\"c-src\">        <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"308\"><span class=\"c-no\">308</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"309\"><span class=\"c-no\">309</span><span class=\"c-src\">    revoked = data.get(<span class=\"c-str\">&quot;revoked_tokens&quot;</span>, [])</span></div>\n<div class=\"c-line\" data-line=\"310\"><span class=\"c-no\">310</span><span class=\"c-src\">    meta = data.get(<span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span>, {})</span></div>\n<div class=\"c-line\" data-line=\"311\"><span class=\"c-no\">311</span><span class=\"c-src\">    current_time = int(time.time())</span></div>\n<div class=\"c-line\" data-line=\"312\"><span class=\"c-no\">312</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"313\"><span class=\"c-no\">313</span><span class=\"c-src\">    <span class=\"c-com\"># Remove expired tokens</span></span></div>\n<div class=\"c-line\" data-line=\"314\"><span class=\"c-no\">314</span><span class=\"c-src\">    cleaned_revoked = []</span></div>\n<div class=\"c-line\" data-line=\"315\"><span class=\"c-no\">315</span><span class=\"c-src\">    cleaned_meta = {}</span></div>\n<div class=\"c-line\" data-line=\"316\"><span class=\"c-no\">316</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"317\"><span class=\"c-no\">317</span><span class=\"c-src\">    <span class=\"c-kw\">for</span> jti <span class=\"c-kw\">in</span> revoked:</span></div>\n<div class=\"c-line\" data-line=\"318\"><span class=\"c-no\">318</span><span class=\"c-src\">        exp = meta.get(jti, 0)</span></div>\n<div class=\"c-line\" data-line=\"319\"><span class=\"c-no\">319</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> exp &gt; current_time:</span></div>\n<div class=\"c-line\" data-line=\"320\"><span class=\"c-no\">320</span><span class=\"c-src\">            cleaned_revoked.append(jti)</span></div>\n<div class=\"c-line\" data-line=\"321\"><span class=\"c-no\">321</span><span class=\"c-src\">            cleaned_meta[jti] = exp</span></div>\n<div class=\"c-line\" data-line=\"322\"><span class=\"c-no\">322</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"323\"><span class=\"c-no\">323</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> len(cleaned_revoked) &lt; len(revoked):</span></div>\n<div class=\"c-line\" data-line=\"324\"><span class=\"c-no\">324</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;revoked_tokens&quot;</span>] = cleaned_revoked</span></div>\n<div class=\"c-line\" data-line=\"325\"><span class=\"c-no\">325</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span>] = cleaned_meta</span></div>\n<div class=\"c-line\" data-line=\"326\"><span class=\"c-no\">326</span><span class=\"c-src\">        _save_auth_data(data)</span></div>\n<div class=\"c-line\" data-line=\"327\"><span class=\"c-no\">327</span><span class=\"c-src\">        logger.info(</span></div>\n<div class=\"c-line\" data-line=\"328\"><span class=\"c-no\">328</span><span class=\"c-src\">            <span class=\"c-str\">&quot;Cleaned %d expired tokens from revocation list&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"329\"><span class=\"c-no\">329</span><span class=\"c-src\">            len(revoked) - len(cleaned_revoked),</span></div>\n<div class=\"c-line\" data-line=\"330\"><span class=\"c-no\">330</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"331\"><span class=\"c-no\">331</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"332\"><span class=\"c-no\">332</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"333\"><span class=\"c-no\">333</span><span class=\"c-src\"><span class=\"c-kw\">def</span> is_auth_enabled() -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"334\"><span class=\"c-no\">334</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Check whether authentication <span class=\"c-kw\">is</span> enabled via environment variable.</span></div>\n<div class=\"c-line\" data-line=\"335\"><span class=\"c-no\">335</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"336\"><span class=\"c-no\">336</span><span class=\"c-src\">    Returns ``<span class=\"c-kw\">True</span>`` when ``QWENPAW_AUTH_ENABLED`` <span class=\"c-kw\">is</span> set to a truthy</span></div>\n<div class=\"c-line\" data-line=\"337\"><span class=\"c-no\">337</span><span class=\"c-src\">    value (``true``, ``1``, ``yes``).  The presence of a registered</span></div>\n<div class=\"c-line\" data-line=\"338\"><span class=\"c-no\">338</span><span class=\"c-src\">    user <span class=\"c-kw\">is</span> checked separately by the middleware so that the first</span></div>\n<div class=\"c-line\" data-line=\"339\"><span class=\"c-no\">339</span><span class=\"c-src\">    user can still reach the registration page.</span></div>\n<div class=\"c-line\" data-line=\"340\"><span class=\"c-no\">340</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"341\"><span class=\"c-no\">341</span><span class=\"c-src\">    env_flag = EnvVarLoader.get_str(<span class=\"c-str\">&quot;QWENPAW_AUTH_ENABLED&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>).strip().lower()</span></div>\n<div class=\"c-line\" data-line=\"342\"><span class=\"c-no\">342</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> env_flag <span class=\"c-kw\">in</span> (<span class=\"c-str\">&quot;true&quot;</span>, <span class=\"c-str\">&quot;1&quot;</span>, <span class=\"c-str\">&quot;yes&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"343\"><span class=\"c-no\">343</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"344\"><span class=\"c-no\">344</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"345\"><span class=\"c-no\">345</span><span class=\"c-src\"><span class=\"c-kw\">def</span> has_registered_users() -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"346\"><span class=\"c-no\">346</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Return ``True`` if a user has been registered.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"347\"><span class=\"c-no\">347</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"348\"><span class=\"c-no\">348</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> bool(data.get(<span class=\"c-str\">&quot;user&quot;</span>))</span></div>\n<div class=\"c-line\" data-line=\"349\"><span class=\"c-no\">349</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"350\"><span class=\"c-no\">350</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"351\"><span class=\"c-no\">351</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"352\"><span class=\"c-no\">352</span><span class=\"c-src\"><span class=\"c-com\"># Registration (single-user)</span></span></div>\n<div class=\"c-line\" data-line=\"353\"><span class=\"c-no\">353</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"354\"><span class=\"c-no\">354</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"355\"><span class=\"c-no\">355</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"356\"><span class=\"c-no\">356</span><span class=\"c-src\"><span class=\"c-kw\">def</span> register_user(</span></div>\n<div class=\"c-line\" data-line=\"357\"><span class=\"c-no\">357</span><span class=\"c-src\">    username: str,</span></div>\n<div class=\"c-line\" data-line=\"358\"><span class=\"c-no\">358</span><span class=\"c-src\">    password: str,</span></div>\n<div class=\"c-line\" data-line=\"359\"><span class=\"c-no\">359</span><span class=\"c-src\">    expiry_seconds: Optional[int] = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"360\"><span class=\"c-no\">360</span><span class=\"c-src\">) -&gt; Optional[str]:</span></div>\n<div class=\"c-line\" data-line=\"361\"><span class=\"c-no\">361</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Register the single user account.</span></div>\n<div class=\"c-line\" data-line=\"362\"><span class=\"c-no\">362</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"363\"><span class=\"c-no\">363</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"364\"><span class=\"c-no\">364</span><span class=\"c-src\">        username: The username to register.</span></div>\n<div class=\"c-line\" data-line=\"365\"><span class=\"c-no\">365</span><span class=\"c-src\">        password: The password to register.</span></div>\n<div class=\"c-line\" data-line=\"366\"><span class=\"c-no\">366</span><span class=\"c-src\">        expiry_seconds: Custom token expiry time <span class=\"c-kw\">in</span> seconds.</span></div>\n<div class=\"c-line\" data-line=\"367\"><span class=\"c-no\">367</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"368\"><span class=\"c-no\">368</span><span class=\"c-src\">    Returns a token on success, ``<span class=\"c-kw\">None</span>`` <span class=\"c-kw\">if</span> a user already exists.</span></div>\n<div class=\"c-line\" data-line=\"369\"><span class=\"c-no\">369</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"370\"><span class=\"c-no\">370</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"371\"><span class=\"c-no\">371</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"372\"><span class=\"c-no\">372</span><span class=\"c-src\">    <span class=\"c-com\"># Only one user allowed</span></span></div>\n<div class=\"c-line\" data-line=\"373\"><span class=\"c-no\">373</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> data.get(<span class=\"c-str\">&quot;user&quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"374\"><span class=\"c-no\">374</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"375\"><span class=\"c-no\">375</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"376\"><span class=\"c-no\">376</span><span class=\"c-src\">    pw_hash, salt = _hash_password(password)</span></div>\n<div class=\"c-line\" data-line=\"377\"><span class=\"c-no\">377</span><span class=\"c-src\">    data[<span class=\"c-str\">&quot;user&quot;</span>] = {</span></div>\n<div class=\"c-line\" data-line=\"378\"><span class=\"c-no\">378</span><span class=\"c-src\">        <span class=\"c-str\">&quot;username&quot;</span>: username,</span></div>\n<div class=\"c-line\" data-line=\"379\"><span class=\"c-no\">379</span><span class=\"c-src\">        <span class=\"c-str\">&quot;password_hash&quot;</span>: pw_hash,</span></div>\n<div class=\"c-line\" data-line=\"380\"><span class=\"c-no\">380</span><span class=\"c-src\">        <span class=\"c-str\">&quot;password_salt&quot;</span>: salt,</span></div>\n<div class=\"c-line\" data-line=\"381\"><span class=\"c-no\">381</span><span class=\"c-src\">    }</span></div>\n<div class=\"c-line\" data-line=\"382\"><span class=\"c-no\">382</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"383\"><span class=\"c-no\">383</span><span class=\"c-src\">    <span class=\"c-com\"># Ensure jwt_secret exists</span></span></div>\n<div class=\"c-line\" data-line=\"384\"><span class=\"c-no\">384</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> data.get(<span class=\"c-str\">&quot;jwt_secret&quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"385\"><span class=\"c-no\">385</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;jwt_secret&quot;</span>] = secrets.token_hex(32)</span></div>\n<div class=\"c-line\" data-line=\"386\"><span class=\"c-no\">386</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"387\"><span class=\"c-no\">387</span><span class=\"c-src\">    _save_auth_data(data)</span></div>\n<div class=\"c-line\" data-line=\"388\"><span class=\"c-no\">388</span><span class=\"c-src\">    logger.info(<span class=\"c-str\">&quot;User &#x27;%s&#x27; registered&quot;</span>, username)</span></div>\n<div class=\"c-line\" data-line=\"389\"><span class=\"c-no\">389</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> create_token(username, expiry_seconds)</span></div>\n<div class=\"c-line\" data-line=\"390\"><span class=\"c-no\">390</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"391\"><span class=\"c-no\">391</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"392\"><span class=\"c-no\">392</span><span class=\"c-src\"><span class=\"c-kw\">def</span> auto_register_from_env() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"393\"><span class=\"c-no\">393</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Auto-register admin user <span class=\"c-kw\">from</span> environment variables.</span></div>\n<div class=\"c-line\" data-line=\"394\"><span class=\"c-no\">394</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"395\"><span class=\"c-no\">395</span><span class=\"c-src\">    Called once during application startup.  If ``QWENPAW_AUTH_ENABLED``</span></div>\n<div class=\"c-line\" data-line=\"396\"><span class=\"c-no\">396</span><span class=\"c-src\">    <span class=\"c-kw\">is</span> truthy <span class=\"c-kw\">and</span> both ``QWENPAW_AUTH_USERNAME`` <span class=\"c-kw\">and</span> ``QWENPAW_AUTH_PASSWORD``</span></div>\n<div class=\"c-line\" data-line=\"397\"><span class=\"c-no\">397</span><span class=\"c-src\">    are set, the admin account <span class=\"c-kw\">is</span> created automatically — useful <span class=\"c-kw\">for</span></span></div>\n<div class=\"c-line\" data-line=\"398\"><span class=\"c-no\">398</span><span class=\"c-src\">    Docker, Kubernetes, server-panel, <span class=\"c-kw\">and</span> other automated deployments</span></div>\n<div class=\"c-line\" data-line=\"399\"><span class=\"c-no\">399</span><span class=\"c-src\">    where interactive web registration <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> practical.</span></div>\n<div class=\"c-line\" data-line=\"400\"><span class=\"c-no\">400</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"401\"><span class=\"c-no\">401</span><span class=\"c-src\">    Skips silently when:</span></div>\n<div class=\"c-line\" data-line=\"402\"><span class=\"c-no\">402</span><span class=\"c-src\">    - authentication <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> enabled</span></div>\n<div class=\"c-line\" data-line=\"403\"><span class=\"c-no\">403</span><span class=\"c-src\">    - a user has already been registered</span></div>\n<div class=\"c-line\" data-line=\"404\"><span class=\"c-no\">404</span><span class=\"c-src\">    - either env var <span class=\"c-kw\">is</span> missing <span class=\"c-kw\">or</span> empty</span></div>\n<div class=\"c-line\" data-line=\"405\"><span class=\"c-no\">405</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"406\"><span class=\"c-no\">406</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> is_auth_enabled():</span></div>\n<div class=\"c-line\" data-line=\"407\"><span class=\"c-no\">407</span><span class=\"c-src\">        <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"408\"><span class=\"c-no\">408</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> has_registered_users():</span></div>\n<div class=\"c-line\" data-line=\"409\"><span class=\"c-no\">409</span><span class=\"c-src\">        <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"410\"><span class=\"c-no\">410</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"411\"><span class=\"c-no\">411</span><span class=\"c-src\">    username = EnvVarLoader.get_str(<span class=\"c-str\">&quot;QWENPAW_AUTH_USERNAME&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>).strip()</span></div>\n<div class=\"c-line\" data-line=\"412\"><span class=\"c-no\">412</span><span class=\"c-src\">    password = EnvVarLoader.get_str(<span class=\"c-str\">&quot;QWENPAW_AUTH_PASSWORD&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>).strip()</span></div>\n<div class=\"c-line\" data-line=\"413\"><span class=\"c-no\">413</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> username <span class=\"c-kw\">or</span> <span class=\"c-kw\">not</span> password:</span></div>\n<div class=\"c-line\" data-line=\"414\"><span class=\"c-no\">414</span><span class=\"c-src\">        <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"415\"><span class=\"c-no\">415</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"416\"><span class=\"c-no\">416</span><span class=\"c-src\">    token = register_user(username, password)</span></div>\n<div class=\"c-line\" data-line=\"417\"><span class=\"c-no\">417</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> token:</span></div>\n<div class=\"c-line\" data-line=\"418\"><span class=\"c-no\">418</span><span class=\"c-src\">        logger.info(</span></div>\n<div class=\"c-line\" data-line=\"419\"><span class=\"c-no\">419</span><span class=\"c-src\">            <span class=\"c-str\">&quot;Auto-registered user &#x27;%s&#x27; from environment variables&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"420\"><span class=\"c-no\">420</span><span class=\"c-src\">            username,</span></div>\n<div class=\"c-line\" data-line=\"421\"><span class=\"c-no\">421</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"422\"><span class=\"c-no\">422</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"423\"><span class=\"c-no\">423</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"424\"><span class=\"c-no\">424</span><span class=\"c-src\"><span class=\"c-kw\">def</span> update_credentials(</span></div>\n<div class=\"c-line\" data-line=\"425\"><span class=\"c-no\">425</span><span class=\"c-src\">    current_password: str,</span></div>\n<div class=\"c-line\" data-line=\"426\"><span class=\"c-no\">426</span><span class=\"c-src\">    new_username: Optional[str] = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"427\"><span class=\"c-no\">427</span><span class=\"c-src\">    new_password: Optional[str] = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"428\"><span class=\"c-no\">428</span><span class=\"c-src\">    expiry_seconds: Optional[int] = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"429\"><span class=\"c-no\">429</span><span class=\"c-src\">) -&gt; Optional[str]:</span></div>\n<div class=\"c-line\" data-line=\"430\"><span class=\"c-no\">430</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Update the registered user&<span class=\"c-com\">#x27;s username and/or password.</span></span></div>\n<div class=\"c-line\" data-line=\"431\"><span class=\"c-no\">431</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"432\"><span class=\"c-no\">432</span><span class=\"c-src\">    Requires the current password <span class=\"c-kw\">for</span> verification.  Returns a new</span></div>\n<div class=\"c-line\" data-line=\"433\"><span class=\"c-no\">433</span><span class=\"c-src\">    token on success (because the username may have changed), <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"434\"><span class=\"c-no\">434</span><span class=\"c-src\">    ``<span class=\"c-kw\">None</span>`` <span class=\"c-kw\">if</span> verification fails.</span></div>\n<div class=\"c-line\" data-line=\"435\"><span class=\"c-no\">435</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"436\"><span class=\"c-no\">436</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"437\"><span class=\"c-no\">437</span><span class=\"c-src\">        current_password: The current password <span class=\"c-kw\">for</span> verification.</span></div>\n<div class=\"c-line\" data-line=\"438\"><span class=\"c-no\">438</span><span class=\"c-src\">        new_username: The new username (optional).</span></div>\n<div class=\"c-line\" data-line=\"439\"><span class=\"c-no\">439</span><span class=\"c-src\">        new_password: The new password (optional).</span></div>\n<div class=\"c-line\" data-line=\"440\"><span class=\"c-no\">440</span><span class=\"c-src\">        expiry_seconds: Custom token expiry time <span class=\"c-kw\">in</span> seconds.</span></div>\n<div class=\"c-line\" data-line=\"441\"><span class=\"c-no\">441</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"442\"><span class=\"c-no\">442</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"443\"><span class=\"c-no\">443</span><span class=\"c-src\">    user = data.get(<span class=\"c-str\">&quot;user&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"444\"><span class=\"c-no\">444</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> user:</span></div>\n<div class=\"c-line\" data-line=\"445\"><span class=\"c-no\">445</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"446\"><span class=\"c-no\">446</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"447\"><span class=\"c-no\">447</span><span class=\"c-src\">    stored_hash = user.get(<span class=\"c-str\">&quot;password_hash&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"448\"><span class=\"c-no\">448</span><span class=\"c-src\">    stored_salt = user.get(<span class=\"c-str\">&quot;password_salt&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"449\"><span class=\"c-no\">449</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> verify_password(current_password, stored_hash, stored_salt):</span></div>\n<div class=\"c-line\" data-line=\"450\"><span class=\"c-no\">450</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"451\"><span class=\"c-no\">451</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"452\"><span class=\"c-no\">452</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> new_username <span class=\"c-kw\">and</span> new_username.strip():</span></div>\n<div class=\"c-line\" data-line=\"453\"><span class=\"c-no\">453</span><span class=\"c-src\">        user[<span class=\"c-str\">&quot;username&quot;</span>] = new_username.strip()</span></div>\n<div class=\"c-line\" data-line=\"454\"><span class=\"c-no\">454</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"455\"><span class=\"c-no\">455</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> new_password:</span></div>\n<div class=\"c-line\" data-line=\"456\"><span class=\"c-no\">456</span><span class=\"c-src\">        pw_hash, salt = _hash_password(new_password)</span></div>\n<div class=\"c-line\" data-line=\"457\"><span class=\"c-no\">457</span><span class=\"c-src\">        user[<span class=\"c-str\">&quot;password_hash&quot;</span>] = pw_hash</span></div>\n<div class=\"c-line\" data-line=\"458\"><span class=\"c-no\">458</span><span class=\"c-src\">        user[<span class=\"c-str\">&quot;password_salt&quot;</span>] = salt</span></div>\n<div class=\"c-line\" data-line=\"459\"><span class=\"c-no\">459</span><span class=\"c-src\">        <span class=\"c-com\"># Rotate JWT secret to invalidate all existing sessions</span></span></div>\n<div class=\"c-line\" data-line=\"460\"><span class=\"c-no\">460</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;jwt_secret&quot;</span>] = secrets.token_hex(32)</span></div>\n<div class=\"c-line\" data-line=\"461\"><span class=\"c-no\">461</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"462\"><span class=\"c-no\">462</span><span class=\"c-src\">    data[<span class=\"c-str\">&quot;user&quot;</span>] = user</span></div>\n<div class=\"c-line\" data-line=\"463\"><span class=\"c-no\">463</span><span class=\"c-src\">    _save_auth_data(data)</span></div>\n<div class=\"c-line\" data-line=\"464\"><span class=\"c-no\">464</span><span class=\"c-src\">    logger.info(<span class=\"c-str\">&quot;Credentials updated for user &#x27;%s&#x27;&quot;</span>, user[<span class=\"c-str\">&quot;username&quot;</span>])</span></div>\n<div class=\"c-line\" data-line=\"465\"><span class=\"c-no\">465</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> create_token(user[<span class=\"c-str\">&quot;username&quot;</span>], expiry_seconds)</span></div>\n<div class=\"c-line\" data-line=\"466\"><span class=\"c-no\">466</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"467\"><span class=\"c-no\">467</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"468\"><span class=\"c-no\">468</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"469\"><span class=\"c-no\">469</span><span class=\"c-src\"><span class=\"c-com\"># Authentication</span></span></div>\n<div class=\"c-line\" data-line=\"470\"><span class=\"c-no\">470</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"471\"><span class=\"c-no\">471</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"472\"><span class=\"c-no\">472</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"473\"><span class=\"c-no\">473</span><span class=\"c-src\"><span class=\"c-kw\">def</span> authenticate(</span></div>\n<div class=\"c-line\" data-line=\"474\"><span class=\"c-no\">474</span><span class=\"c-src\">    username: str,</span></div>\n<div class=\"c-line\" data-line=\"475\"><span class=\"c-no\">475</span><span class=\"c-src\">    password: str,</span></div>\n<div class=\"c-line\" data-line=\"476\"><span class=\"c-no\">476</span><span class=\"c-src\">    expiry_seconds: Optional[int] = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"477\"><span class=\"c-no\">477</span><span class=\"c-src\">) -&gt; Optional[str]:</span></div>\n<div class=\"c-line\" data-line=\"478\"><span class=\"c-no\">478</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Authenticate *username* / *password*.  Returns a token <span class=\"c-kw\">if</span> valid.</span></div>\n<div class=\"c-line\" data-line=\"479\"><span class=\"c-no\">479</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"480\"><span class=\"c-no\">480</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"481\"><span class=\"c-no\">481</span><span class=\"c-src\">        username: The username to authenticate.</span></div>\n<div class=\"c-line\" data-line=\"482\"><span class=\"c-no\">482</span><span class=\"c-src\">        password: The password to verify.</span></div>\n<div class=\"c-line\" data-line=\"483\"><span class=\"c-no\">483</span><span class=\"c-src\">        expiry_seconds: Custom token expiry time <span class=\"c-kw\">in</span> seconds.</span></div>\n<div class=\"c-line\" data-line=\"484\"><span class=\"c-no\">484</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"485\"><span class=\"c-no\">485</span><span class=\"c-src\">    data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"486\"><span class=\"c-no\">486</span><span class=\"c-src\">    user = data.get(<span class=\"c-str\">&quot;user&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"487\"><span class=\"c-no\">487</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> user:</span></div>\n<div class=\"c-line\" data-line=\"488\"><span class=\"c-no\">488</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"489\"><span class=\"c-no\">489</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> user.get(<span class=\"c-str\">&quot;username&quot;</span>) != username:</span></div>\n<div class=\"c-line\" data-line=\"490\"><span class=\"c-no\">490</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"491\"><span class=\"c-no\">491</span><span class=\"c-src\">    stored_hash = user.get(<span class=\"c-str\">&quot;password_hash&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"492\"><span class=\"c-no\">492</span><span class=\"c-src\">    stored_salt = user.get(<span class=\"c-str\">&quot;password_salt&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"493\"><span class=\"c-no\">493</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> (</span></div>\n<div class=\"c-line\" data-line=\"494\"><span class=\"c-no\">494</span><span class=\"c-src\">        stored_hash</span></div>\n<div class=\"c-line\" data-line=\"495\"><span class=\"c-no\">495</span><span class=\"c-src\">        <span class=\"c-kw\">and</span> stored_salt</span></div>\n<div class=\"c-line\" data-line=\"496\"><span class=\"c-no\">496</span><span class=\"c-src\">        <span class=\"c-kw\">and</span> verify_password(password, stored_hash, stored_salt)</span></div>\n<div class=\"c-line\" data-line=\"497\"><span class=\"c-no\">497</span><span class=\"c-src\">    ):</span></div>\n<div class=\"c-line\" data-line=\"498\"><span class=\"c-no\">498</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> create_token(username, expiry_seconds)</span></div>\n<div class=\"c-line\" data-line=\"499\"><span class=\"c-no\">499</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"500\"><span class=\"c-no\">500</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"501\"><span class=\"c-no\">501</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"502\"><span class=\"c-no\">502</span><span class=\"c-src\"><span class=\"c-kw\">def</span> revoke_token(token: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"503\"><span class=\"c-no\">503</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Revoke a single token by adding its jti to the blacklist.</span></div>\n<div class=\"c-line\" data-line=\"504\"><span class=\"c-no\">504</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"505\"><span class=\"c-no\">505</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"506\"><span class=\"c-no\">506</span><span class=\"c-src\">        token: The token string to revoke.</span></div>\n<div class=\"c-line\" data-line=\"507\"><span class=\"c-no\">507</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"508\"><span class=\"c-no\">508</span><span class=\"c-src\">    Returns <span class=\"c-kw\">True</span> on success, <span class=\"c-kw\">False</span> on failure.</span></div>\n<div class=\"c-line\" data-line=\"509\"><span class=\"c-no\">509</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"510\"><span class=\"c-no\">510</span><span class=\"c-src\">    <span class=\"c-kw\">import</span> base64</span></div>\n<div class=\"c-line\" data-line=\"511\"><span class=\"c-no\">511</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"512\"><span class=\"c-no\">512</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"513\"><span class=\"c-no\">513</span><span class=\"c-src\">        <span class=\"c-com\"># Extract jti and exp from token</span></span></div>\n<div class=\"c-line\" data-line=\"514\"><span class=\"c-no\">514</span><span class=\"c-src\">        parts = token.split(<span class=\"c-str\">&quot;.&quot;</span>, 1)</span></div>\n<div class=\"c-line\" data-line=\"515\"><span class=\"c-no\">515</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> len(parts) != 2:</span></div>\n<div class=\"c-line\" data-line=\"516\"><span class=\"c-no\">516</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"517\"><span class=\"c-no\">517</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"518\"><span class=\"c-no\">518</span><span class=\"c-src\">        payload_b64 = parts[0]</span></div>\n<div class=\"c-line\" data-line=\"519\"><span class=\"c-no\">519</span><span class=\"c-src\">        payload = json.loads(base64.urlsafe_b64decode(payload_b64))</span></div>\n<div class=\"c-line\" data-line=\"520\"><span class=\"c-no\">520</span><span class=\"c-src\">        jti = payload.get(<span class=\"c-str\">&quot;jti&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"521\"><span class=\"c-no\">521</span><span class=\"c-src\">        exp = payload.get(<span class=\"c-str\">&quot;exp&quot;</span>, 0)</span></div>\n<div class=\"c-line\" data-line=\"522\"><span class=\"c-no\">522</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"523\"><span class=\"c-no\">523</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> jti:</span></div>\n<div class=\"c-line\" data-line=\"524\"><span class=\"c-no\">524</span><span class=\"c-src\">            logger.warning(<span class=\"c-str\">&quot;Token has no jti, cannot revoke individually&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"525\"><span class=\"c-no\">525</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"526\"><span class=\"c-no\">526</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"527\"><span class=\"c-no\">527</span><span class=\"c-src\">        _add_to_revocation_list(jti, exp)</span></div>\n<div class=\"c-line\" data-line=\"528\"><span class=\"c-no\">528</span><span class=\"c-src\">        logger.info(<span class=\"c-str\">&quot;Token %s revoked&quot;</span>, jti[:8])</span></div>\n<div class=\"c-line\" data-line=\"529\"><span class=\"c-no\">529</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"530\"><span class=\"c-no\">530</span><span class=\"c-src\">        <span class=\"c-com\"># Clean up expired tokens periodically</span></span></div>\n<div class=\"c-line\" data-line=\"531\"><span class=\"c-no\">531</span><span class=\"c-src\">        _clean_expired_revocations()</span></div>\n<div class=\"c-line\" data-line=\"532\"><span class=\"c-no\">532</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"533\"><span class=\"c-no\">533</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"534\"><span class=\"c-no\">534</span><span class=\"c-src\">    <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> exc:</span></div>\n<div class=\"c-line\" data-line=\"535\"><span class=\"c-no\">535</span><span class=\"c-src\">        logger.error(<span class=\"c-str\">&quot;Failed to revoke token: %s&quot;</span>, exc)</span></div>\n<div class=\"c-line\" data-line=\"536\"><span class=\"c-no\">536</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"537\"><span class=\"c-no\">537</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"538\"><span class=\"c-no\">538</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"539\"><span class=\"c-no\">539</span><span class=\"c-src\"><span class=\"c-kw\">def</span> revoke_all_tokens() -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"540\"><span class=\"c-no\">540</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Revoke all existing tokens by rotating the JWT secret.</span></div>\n<div class=\"c-line\" data-line=\"541\"><span class=\"c-no\">541</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"542\"><span class=\"c-no\">542</span><span class=\"c-src\">    This will invalidate all tokens that were issued before this call.</span></div>\n<div class=\"c-line\" data-line=\"543\"><span class=\"c-no\">543</span><span class=\"c-src\">    Also clears the revocation list since all tokens are invalid anyway.</span></div>\n<div class=\"c-line\" data-line=\"544\"><span class=\"c-no\">544</span><span class=\"c-src\">    Returns <span class=\"c-kw\">True</span> on success, <span class=\"c-kw\">False</span> on failure.</span></div>\n<div class=\"c-line\" data-line=\"545\"><span class=\"c-no\">545</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"546\"><span class=\"c-no\">546</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"547\"><span class=\"c-no\">547</span><span class=\"c-src\">        data = _load_auth_data()</span></div>\n<div class=\"c-line\" data-line=\"548\"><span class=\"c-no\">548</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> data.get(<span class=\"c-str\">&quot;_auth_load_error&quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"549\"><span class=\"c-no\">549</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"550\"><span class=\"c-no\">550</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"551\"><span class=\"c-no\">551</span><span class=\"c-src\">        <span class=\"c-com\"># Rotate JWT secret to invalidate all existing tokens</span></span></div>\n<div class=\"c-line\" data-line=\"552\"><span class=\"c-no\">552</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;jwt_secret&quot;</span>] = secrets.token_hex(32)</span></div>\n<div class=\"c-line\" data-line=\"553\"><span class=\"c-no\">553</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"554\"><span class=\"c-no\">554</span><span class=\"c-src\">        <span class=\"c-com\"># Clear revocation list since all tokens are now invalid</span></span></div>\n<div class=\"c-line\" data-line=\"555\"><span class=\"c-no\">555</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;revoked_tokens&quot;</span>] = []</span></div>\n<div class=\"c-line\" data-line=\"556\"><span class=\"c-no\">556</span><span class=\"c-src\">        data[<span class=\"c-str\">&quot;revoked_tokens_meta&quot;</span>] = {}</span></div>\n<div class=\"c-line\" data-line=\"557\"><span class=\"c-no\">557</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"558\"><span class=\"c-no\">558</span><span class=\"c-src\">        _save_auth_data(data)</span></div>\n<div class=\"c-line\" data-line=\"559\"><span class=\"c-no\">559</span><span class=\"c-src\">        logger.info(<span class=\"c-str\">&quot;All tokens revoked (JWT secret rotated)&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"560\"><span class=\"c-no\">560</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"561\"><span class=\"c-no\">561</span><span class=\"c-src\">    <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> exc:</span></div>\n<div class=\"c-line\" data-line=\"562\"><span class=\"c-no\">562</span><span class=\"c-src\">        logger.error(<span class=\"c-str\">&quot;Failed to revoke tokens: %s&quot;</span>, exc)</span></div>\n<div class=\"c-line\" data-line=\"563\"><span class=\"c-no\">563</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"564\"><span class=\"c-no\">564</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"565\"><span class=\"c-no\">565</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"566\"><span class=\"c-no\">566</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"567\"><span class=\"c-no\">567</span><span class=\"c-src\"><span class=\"c-com\"># FastAPI middleware</span></span></div>\n<div class=\"c-line\" data-line=\"568\"><span class=\"c-no\">568</span><span class=\"c-src\"><span class=\"c-com\"># ---------------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"569\"><span class=\"c-no\">569</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"570\"><span class=\"c-no\">570</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"571\"><span class=\"c-no\">571</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _resolve_client_ip(request: Request) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"572\"><span class=\"c-no\">572</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Return the real client IP, respecting reverse-proxy headers.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"573\"><span class=\"c-no\">573</span><span class=\"c-src\">    forwarded_for = request.headers.get(<span class=\"c-str\">&quot;x-forwarded-for&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"574\"><span class=\"c-no\">574</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> forwarded_for:</span></div>\n<div class=\"c-line\" data-line=\"575\"><span class=\"c-no\">575</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> forwarded_for.split(<span class=\"c-str\">&quot;,&quot;</span>)[0].strip()</span></div>\n<div class=\"c-line\" data-line=\"576\"><span class=\"c-no\">576</span><span class=\"c-src\">    real_ip = request.headers.get(<span class=\"c-str\">&quot;x-real-ip&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"577\"><span class=\"c-no\">577</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> real_ip:</span></div>\n<div class=\"c-line\" data-line=\"578\"><span class=\"c-no\">578</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> real_ip.strip()</span></div>\n<div class=\"c-line\" data-line=\"579\"><span class=\"c-no\">579</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> request.client.host <span class=\"c-kw\">if</span> request.client <span class=\"c-kw\">else</span> <span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"580\"><span class=\"c-no\">580</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"581\"><span class=\"c-no\">581</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"582\"><span class=\"c-no\">582</span><span class=\"c-src\"><span class=\"c-com\"># Make this function available at module level so it can be</span></span></div>\n<div class=\"c-line\" data-line=\"583\"><span class=\"c-no\">583</span><span class=\"c-src\"><span class=\"c-com\"># imported from routers</span></span></div>\n<div class=\"c-line\" data-line=\"584\"><span class=\"c-no\">584</span><span class=\"c-src\">resolve_client_ip = _resolve_client_ip</span></div>\n<div class=\"c-line\" data-line=\"585\"><span class=\"c-no\">585</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"586\"><span class=\"c-no\">586</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"587\"><span class=\"c-no\">587</span><span class=\"c-src\"><span class=\"c-com\"># Cached config for hot-path auth checks (avoids disk read per request)</span></span></div>\n<div class=\"c-line\" data-line=\"588\"><span class=\"c-no\">588</span><span class=\"c-src\">_auth_config_cache: tuple = (0, <span class=\"c-kw\">None</span>)  <span class=\"c-com\"># (mtime_ns, config)</span></span></div>\n<div class=\"c-line\" data-line=\"589\"><span class=\"c-no\">589</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"590\"><span class=\"c-no\">590</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"591\"><span class=\"c-no\">591</span><span class=\"c-src\"><span class=\"c-kw\">def</span> _get_config_cached():</span></div>\n<div class=\"c-line\" data-line=\"592\"><span class=\"c-no\">592</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Return config with mtime-based cache (stat is ~1us vs read ~1ms).&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"593\"><span class=\"c-no\">593</span><span class=\"c-src\">    <span class=\"c-kw\">global</span> _auth_config_cache  <span class=\"c-com\"># noqa: PLW0603</span></span></div>\n<div class=\"c-line\" data-line=\"594\"><span class=\"c-no\">594</span><span class=\"c-src\">    <span class=\"c-kw\">from</span> ..config <span class=\"c-kw\">import</span> load_config</span></div>\n<div class=\"c-line\" data-line=\"595\"><span class=\"c-no\">595</span><span class=\"c-src\">    <span class=\"c-kw\">from</span> ..config.utils <span class=\"c-kw\">import</span> get_config_path</span></div>\n<div class=\"c-line\" data-line=\"596\"><span class=\"c-no\">596</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"597\"><span class=\"c-no\">597</span><span class=\"c-src\">    config_path = get_config_path()</span></div>\n<div class=\"c-line\" data-line=\"598\"><span class=\"c-no\">598</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"599\"><span class=\"c-no\">599</span><span class=\"c-src\">        mtime_ns = config_path.stat().st_mtime_ns</span></div>\n<div class=\"c-line\" data-line=\"600\"><span class=\"c-no\">600</span><span class=\"c-src\">    <span class=\"c-kw\">except</span> OSError:</span></div>\n<div class=\"c-line\" data-line=\"601\"><span class=\"c-no\">601</span><span class=\"c-src\">        mtime_ns = 0</span></div>\n<div class=\"c-line\" data-line=\"602\"><span class=\"c-no\">602</span><span class=\"c-src\">    <span class=\"c-kw\">if</span> mtime_ns != _auth_config_cache[0] <span class=\"c-kw\">or</span> _auth_config_cache[1] <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"603\"><span class=\"c-no\">603</span><span class=\"c-src\">        _auth_config_cache = (mtime_ns, load_config())</span></div>\n<div class=\"c-line\" data-line=\"604\"><span class=\"c-no\">604</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> _auth_config_cache[1]</span></div>\n<div class=\"c-line\" data-line=\"605\"><span class=\"c-no\">605</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"606\"><span class=\"c-no\">606</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"607\"><span class=\"c-no\">607</span><span class=\"c-src\"><span class=\"c-kw\">class</span> AuthMiddleware(BaseHTTPMiddleware):</span></div>\n<div class=\"c-line\" data-line=\"608\"><span class=\"c-no\">608</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Middleware that checks Bearer token on protected routes.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"609\"><span class=\"c-no\">609</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"610\"><span class=\"c-no\">610</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> dispatch(</span></div>\n<div class=\"c-line\" data-line=\"611\"><span class=\"c-no\">611</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"612\"><span class=\"c-no\">612</span><span class=\"c-src\">        request: Request,</span></div>\n<div class=\"c-line\" data-line=\"613\"><span class=\"c-no\">613</span><span class=\"c-src\">        call_next,</span></div>\n<div class=\"c-line\" data-line=\"614\"><span class=\"c-no\">614</span><span class=\"c-src\">    ) -&gt; Response:</span></div>\n<div class=\"c-line\" data-line=\"615\"><span class=\"c-no\">615</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Check Bearer token on protected API routes; skip public paths.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"616\"><span class=\"c-no\">616</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._should_skip_auth(request):</span></div>\n<div class=\"c-line\" data-line=\"617\"><span class=\"c-no\">617</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">await</span> call_next(request)</span></div>\n<div class=\"c-line\" data-line=\"618\"><span class=\"c-no\">618</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"619\"><span class=\"c-no\">619</span><span class=\"c-src\">        token = <span class=\"c-kw\">self</span>._extract_token(request)</span></div>\n<div class=\"c-line\" data-line=\"620\"><span class=\"c-no\">620</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> token:</span></div>\n<div class=\"c-line\" data-line=\"621\"><span class=\"c-no\">621</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> Response(</span></div>\n<div class=\"c-line\" data-line=\"622\"><span class=\"c-no\">622</span><span class=\"c-src\">                content=json.dumps({<span class=\"c-str\">&quot;detail&quot;</span>: <span class=\"c-str\">&quot;Not authenticated&quot;</span>}),</span></div>\n<div class=\"c-line\" data-line=\"623\"><span class=\"c-no\">623</span><span class=\"c-src\">                status_code=401,</span></div>\n<div class=\"c-line\" data-line=\"624\"><span class=\"c-no\">624</span><span class=\"c-src\">                media_type=<span class=\"c-str\">&quot;application/json&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"625\"><span class=\"c-no\">625</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"626\"><span class=\"c-no\">626</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"627\"><span class=\"c-no\">627</span><span class=\"c-src\">        user = verify_token(token)</span></div>\n<div class=\"c-line\" data-line=\"628\"><span class=\"c-no\">628</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> user <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"629\"><span class=\"c-no\">629</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> Response(</span></div>\n<div class=\"c-line\" data-line=\"630\"><span class=\"c-no\">630</span><span class=\"c-src\">                content=json.dumps(</span></div>\n<div class=\"c-line\" data-line=\"631\"><span class=\"c-no\">631</span><span class=\"c-src\">                    {<span class=\"c-str\">&quot;detail&quot;</span>: <span class=\"c-str\">&quot;Invalid or expired token&quot;</span>},</span></div>\n<div class=\"c-line\" data-line=\"632\"><span class=\"c-no\">632</span><span class=\"c-src\">                ),</span></div>\n<div class=\"c-line\" data-line=\"633\"><span class=\"c-no\">633</span><span class=\"c-src\">                status_code=401,</span></div>\n<div class=\"c-line\" data-line=\"634\"><span class=\"c-no\">634</span><span class=\"c-src\">                media_type=<span class=\"c-str\">&quot;application/json&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"635\"><span class=\"c-no\">635</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"636\"><span class=\"c-no\">636</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"637\"><span class=\"c-no\">637</span><span class=\"c-src\">        request.state.user = user</span></div>\n<div class=\"c-line\" data-line=\"638\"><span class=\"c-no\">638</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">await</span> call_next(request)</span></div>\n<div class=\"c-line\" data-line=\"639\"><span class=\"c-no\">639</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"640\"><span class=\"c-no\">640</span><span class=\"c-src\">    @staticmethod</span></div>\n<div class=\"c-line\" data-line=\"641\"><span class=\"c-no\">641</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _should_skip_auth(request: Request) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"642\"><span class=\"c-no\">642</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Return ``True`` when the request does not require auth.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"643\"><span class=\"c-no\">643</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> is_auth_enabled() <span class=\"c-kw\">or</span> <span class=\"c-kw\">not</span> has_registered_users():</span></div>\n<div class=\"c-line\" data-line=\"644\"><span class=\"c-no\">644</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"645\"><span class=\"c-no\">645</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"646\"><span class=\"c-no\">646</span><span class=\"c-src\">        path = request.url.path</span></div>\n<div class=\"c-line\" data-line=\"647\"><span class=\"c-no\">647</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"648\"><span class=\"c-no\">648</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> request.method == <span class=\"c-str\">&quot;OPTIONS&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"649\"><span class=\"c-no\">649</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"650\"><span class=\"c-no\">650</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"651\"><span class=\"c-no\">651</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> path <span class=\"c-kw\">in</span> _PUBLIC_PATHS <span class=\"c-kw\">or</span> any(</span></div>\n<div class=\"c-line\" data-line=\"652\"><span class=\"c-no\">652</span><span class=\"c-src\">            path.startswith(p) <span class=\"c-kw\">for</span> p <span class=\"c-kw\">in</span> _PUBLIC_PREFIXES</span></div>\n<div class=\"c-line\" data-line=\"653\"><span class=\"c-no\">653</span><span class=\"c-src\">        ):</span></div>\n<div class=\"c-line\" data-line=\"654\"><span class=\"c-no\">654</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"655\"><span class=\"c-no\">655</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"656\"><span class=\"c-no\">656</span><span class=\"c-src\">        <span class=\"c-com\"># Only protect /api/ routes</span></span></div>\n<div class=\"c-line\" data-line=\"657\"><span class=\"c-no\">657</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> path.startswith(<span class=\"c-str\">&quot;/api/&quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"658\"><span class=\"c-no\">658</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"659\"><span class=\"c-no\">659</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"660\"><span class=\"c-no\">660</span><span class=\"c-src\">        <span class=\"c-com\"># Check if client host is in allow_no_auth_hosts whitelist</span></span></div>\n<div class=\"c-line\" data-line=\"661\"><span class=\"c-no\">661</span><span class=\"c-src\">        client_host = resolve_client_ip(request)</span></div>\n<div class=\"c-line\" data-line=\"662\"><span class=\"c-no\">662</span><span class=\"c-src\">        config = _get_config_cached()</span></div>\n<div class=\"c-line\" data-line=\"663\"><span class=\"c-no\">663</span><span class=\"c-src\">        allowed_hosts = config.security.allow_no_auth_hosts</span></div>\n<div class=\"c-line\" data-line=\"664\"><span class=\"c-no\">664</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> client_host <span class=\"c-kw\">in</span> allowed_hosts</span></div>\n<div class=\"c-line\" data-line=\"665\"><span class=\"c-no\">665</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"666\"><span class=\"c-no\">666</span><span class=\"c-src\">    @staticmethod</span></div>\n<div class=\"c-line\" data-line=\"667\"><span class=\"c-no\">667</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _extract_token(request: Request) -&gt; Optional[str]:</span></div>\n<div class=\"c-line\" data-line=\"668\"><span class=\"c-no\">668</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Extract Bearer token from header or WebSocket query param.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"669\"><span class=\"c-no\">669</span><span class=\"c-src\">        auth_header = request.headers.get(<span class=\"c-str\">&quot;Authorization&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"670\"><span class=\"c-no\">670</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> auth_header.startswith(<span class=\"c-str\">&quot;Bearer &quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"671\"><span class=\"c-no\">671</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> auth_header[7:]</span></div>\n<div class=\"c-line\" data-line=\"672\"><span class=\"c-no\">672</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-str\">&quot;upgrade&quot;</span> <span class=\"c-kw\">in</span> request.headers.get(<span class=\"c-str\">&quot;connection&quot;</span>, <span class=\"c-str\">&quot;&quot;</span>).lower():</span></div>\n<div class=\"c-line\" data-line=\"673\"><span class=\"c-no\">673</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> request.query_params.get(<span class=\"c-str\">&quot;token&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"674\"><span class=\"c-no\">674</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"675\"><span class=\"c-no\">675</span><span class=\"c-src\">        token = request.query_params.get(<span class=\"c-str\">&quot;token&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"676\"><span class=\"c-no\">676</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> token:</span></div>\n<div class=\"c-line\" data-line=\"677\"><span class=\"c-no\">677</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> token</span></div>\n<div class=\"c-line\" data-line=\"678\"><span class=\"c-no\">678</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"679\"><span class=\"c-no\">679</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 679, "explanation": "auth.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [], "related_docs": ["W11-多Agent协作平台实战(上)"]};
